(() => {
'use strict';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cfg=window.PW_POSA_CONFIG;
if(!window.supabase||!cfg){$('loginError').textContent='Connessione non disponibile. Ricarica la pagina.';return;}
const sb=window.supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_ANON_KEY);
const states={pending:'In attesa',counterproposed:'Controproposta',confirmed:'Confermata',in_progress:'In corso',incomplete:'Lavoro incompleto',completed:'Completata',rejected:'Rifiutata'};
const locked=r=>['confirmed','in_progress','incomplete','completed'].includes(r.status);
const state={user:null,profile:null,installers:[],requests:[],notifications:[],unread:0,view:'calendar',mode:'month',cursor:today(),filter:'',status:'',search:'',filterOpen:false,selected:null,channel:null,loading:false};
const office=()=>['office_scheduler','office_viewer'].includes(state.profile?.role),scheduler=()=>state.profile?.role==='office_scheduler';
const installer=id=>state.installers.find(i=>i.id===id);
const myRequest=r=>installer(r.installer_id)?.profile_id===state.user?.id;
const date=v=>new Date(`${v}T12:00:00`);
function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function today(){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>p.find(v=>v.type===k).value).join('-');}
function shift(v,n){const d=date(v);d.setDate(d.getDate()+n);return iso(d);}
function range(a,b){const out=[];for(let v=a;v<=b;v=shift(v,1)){out.push(v);if(out.length>180)throw Error('Seleziona al massimo 180 giornate.');}return out;}
function fmt(v,long=false){return date(v).toLocaleDateString('it-IT',long?{weekday:'long',day:'numeric',month:'long'}:{day:'2-digit',month:'2-digit',year:'numeric'});}
function money(v){return Number(v).toLocaleString('it-IT',{style:'currency',currency:'EUR'});}
function datesLabel(ds){return ds?.length?ds.length===1?fmt(ds[0]):`${fmt(ds[0])} – ${fmt(ds.at(-1))} · ${ds.length} giorni`:'—';}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),5000);}
function empty(title,copy){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(copy)}</p></div>`;}
function tag(r){return `<span class="tag ${esc(r.status)}">${locked(r)?'🔒 ':''}${states[r.status]}</span>`;}
function showModal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function closeModal(){$('passwordForm')?.reset();state.selected=null;$('modal').close();if(document.body.classList.contains('embedded'))window.parent.postMessage({type:'pw-external-close'},location.origin);}
async function call(name,args){const r=await sb.rpc(name,args);if(r.error)throw new Error(r.error.message);return Array.isArray(r.data)&&r.data.length===1?r.data[0]:r.data;}
async function safe(fn,button){if(button?.disabled)return;try{if(button)button.disabled=true;await fn();}catch(error){console.error('PW Posa Esterni',error);toast(error.message||'Operazione non riuscita. Riprova.');const target=$('modalBody').querySelector('[data-form-error]');if(target)target.textContent=error.message;}finally{if(button?.isConnected)button.disabled=false;}}
async function adminAction(body){
 const result=await sb.functions.invoke('pw-external-admin',{body});
 if(result.error||result.data?.error){let message=result.data?.error;try{if(!message&&result.error?.context?.json)message=(await result.error.context.json()).error;}catch(_){}throw Error(message||'Operazione non riuscita. Riprova.');}
 return result.data;
}
function deleteInstallerForm(id){
 if(!scheduler())return;const i=installer(id);if(!i||i.deleted_at){toast('Account già eliminato.');return;}state.selected=null;
 const count=state.requests.filter(r=>r.installer_id===id).length;
 showModal('Elimina posatore',`<form id="deleteInstallerForm"><p class="delete-name">${esc(i.full_name)}</p><p class="delete-copy">L’account di accesso verrà eliminato e il posatore verrà rimosso dall’elenco. Questa operazione non può essere annullata.</p><div class="notice">Gli incarichi, le date già confermate e i fascicoli rimarranno consultabili dall’ufficio.${count?`<br>Incarichi presenti: <strong>${count}</strong>.`:''}</div><label>Scrivi il nome completo del posatore per confermare<input name="confirmation_name" required autocomplete="off" placeholder="${esc(i.full_name)}"></label><p class="error" data-form-error></p><div class="form-actions"><button type="button" class="btn ghost" data-close>Annulla</button><button type="submit" class="btn danger">${i.deletion_started_at?'Completa eliminazione':'Elimina account'}</button></div></form>`);
 $('deleteInstallerForm').onsubmit=e=>{e.preventDefault();const name=e.currentTarget.elements.confirmation_name.value.trim();safe(async()=>{if(name!==i.full_name)throw Error('Scrivi il nome completo esattamente come indicato.');try{await adminAction({action:'delete_installer',installer_id:i.id,confirmation_name:name});}catch(error){await refresh();throw error;}state.view='installers';await refresh();changed();closeModal();toast('Account del posatore eliminato. Gli incarichi e i fascicoli sono conservati.');},e.submitter);};
}
function dataOf(form){return Object.fromEntries(new FormData(form));}
function changed(){window.parent!==window&&window.parent.postMessage({type:'pw-external-updated'},location.origin);}
async function load(){
 const results=await Promise.all([sb.from('external_requests').select('*').order('created_at',{ascending:false}),sb.from('external_installers').select('*').order('full_name'),sb.from('notifications').select('*').eq('recipient_id',state.user.id).like('notification_type','external_%').order('created_at',{ascending:false}).limit(100),sb.from('notifications').select('id',{head:true,count:'exact'}).eq('recipient_id',state.user.id).like('notification_type','external_%').is('read_at',null)]);
 for(const r of results)if(r.error)throw new Error(r.error.message);
 [state.requests,state.installers,state.notifications]=results.slice(0,3).map(x=>x.data||[]);state.unread=results[3].count||0;
 $('unread').textContent=state.unread;$('unread').hidden=!state.unread;
}
async function refresh(){if(!state.user||state.loading)return;state.loading=true;try{await load();render();}finally{state.loading=false;}}
function filtered(){const q=state.search.trim().toLocaleLowerCase('it');return state.requests.filter(r=>(!state.filter||r.installer_id===state.filter)&&(!state.status||r.status===state.status)&&(!q||[r.reference,r.client_name,r.address,installer(r.installer_id)?.full_name,installer(r.installer_id)?.company].join(' ').toLocaleLowerCase('it').includes(q)));}
function filterHtml(){return `<button class="btn ghost mobile-only mobile-filter-button" data-toggle-filters>Filtri${state.filter||state.status||state.search?" · attivi":""} ▾</button><div class="filters${state.filterOpen?" open":""}"><input id="search" type="search" value="${esc(state.search)}" placeholder="Cerca indirizzo, cliente, riferimento…" aria-label="Cerca incarichi">${office()?`<select id="installerFilter" aria-label="Filtra per posatore"><option value="">Tutti i posatori</option>${state.installers.map(i=>`<option value="${i.id}"${state.filter===i.id?' selected':''}>${esc(i.company||i.full_name)}${i.deleted_at?' · account eliminato':''}</option>`).join('')}</select>`:''}<select id="statusFilter" aria-label="Filtra per stato"><option value="">Tutti gli stati</option>${Object.entries(states).map(([k,v])=>`<option value="${k}"${state.status===k?' selected':''}>${v}</option>`).join('')}</select></div>`;}
function stats(){return `<div class="stats">${[['In attesa',state.requests.filter(r=>['pending','counterproposed'].includes(r.status)).length,'◷'],['Pose confermate',state.requests.filter(r=>['confirmed','in_progress'].includes(r.status)).length,'↗'],['Da completare',state.requests.filter(r=>r.status==='incomplete').length,'!'],['Lavori conclusi',state.requests.filter(r=>r.status==='completed').length,'✓']].map(([label,n,icon])=>`<div class="stat"><div><span>${label}</span><strong>${n}</strong></div><i aria-hidden="true">${icon}</i></div>`).join('')}</div>`;}
function card(r){const i=installer(r.installer_id);return `<article class="request-card"><div class="card-top">${tag(r)}<span class="muted small">${esc(r.reference||'Incarico')}</span></div><h3>${esc(r.client_name||r.address)}</h3><p>${esc(r.address)} · Piano ${esc(r.floor)}</p><p>${esc(datesLabel(r.work_dates))}<br>${esc(r.start_time.slice(0,5))}–${esc(r.end_time.slice(0,5))}${office()?`<br>${esc(i?.company||i?.full_name||'')}`:''}</p><div class="card-bottom"><strong>${money(r.price)}</strong><button class="btn ghost" data-open="${r.id}">Riepilogo ↗</button></div></article>`;}
function chip(r){return `<button type="button" class="event ${r.status}" data-open="${r.id}" title="${esc(`${states[r.status]} · ${r.address} · ${r.start_time.slice(0,5)}`)}"><strong>${locked(r)?'🔒 ':''}${esc(r.start_time.slice(0,5))} · ${esc(r.client_name||r.reference||r.address)}</strong><small>${esc(states[r.status])}${office()?` · ${esc(installer(r.installer_id)?.company||installer(r.installer_id)?.full_name||'')}`:''}</small></button>`;}
function calendar(){
 let days=[],title='';const cur=date(state.cursor);
 if(state.mode==='month'){const start=new Date(cur.getFullYear(),cur.getMonth(),1,12);start.setDate(start.getDate()-(start.getDay()+6)%7);const end=new Date(cur.getFullYear(),cur.getMonth()+1,0,12);end.setDate(end.getDate()+6-(end.getDay()+6)%7);for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1))days.push(iso(d));title=cur.toLocaleDateString('it-IT',{month:'long',year:'numeric'});}
 else if(state.mode==='week'){const start=shift(state.cursor,-(cur.getDay()+6)%7);days=range(start,shift(start,6));title=`${fmt(days[0])} – ${fmt(days.at(-1))}`;}else{days=[state.cursor];title=fmt(state.cursor,true);}
 const rows=filtered().filter(r=>state.status||r.status!=='rejected');
 const onDay=d=>rows.filter(r=>r.work_dates.includes(d)).sort((a,b)=>a.start_time.localeCompare(b.start_time));
 return `${stats()}${filterHtml()}<section class="panel"><div class="toolbar"><h2>${esc(title)}</h2><div class="calendar-controls"><button class="icon-button" data-step="-1" aria-label="Periodo precedente">‹</button><button class="btn ghost" data-today>Oggi</button><button class="icon-button" data-step="1" aria-label="Periodo successivo">›</button><div class="switcher">${[['month','Mese'],['week','Settimana'],['day','Giorno']].map(([v,t])=>`<button data-mode="${v}" class="${state.mode===v?'active':''}" aria-pressed="${state.mode===v}">${t}</button>`).join('')}</div></div></div><div class="legend"><span><i class="dot pending"></i>In attesa</span><span><i class="dot counterproposed"></i>Controproposta</span><span><i class="dot confirmed"></i>🔒 Date impegnate</span></div>${state.mode==='month'?`<div class="weekdays">${['Lun','Mar','Mer','Gio','Ven','Sab','Dom'].map(d=>`<span>${d}</span>`).join('')}</div><div class="month-grid">${days.map(d=>{const items=onDay(d);return `<div class="day${date(d).getMonth()!==cur.getMonth()?' outside':''}${d===today()?' today':''}"><button class="day-number" data-day="${d}" aria-label="Apri ${esc(fmt(d,true))}">${date(d).getDate()}</button>${items.slice(0,2).map(chip).join('')}${items.length>2?`<button class="more-day" data-day="${d}">+${items.length-2} altre</button>`:''}</div>`;}).join('')}</div>`:days.map(d=>`<section class="list-day"><div class="section-row" style="margin-top:0"><h3>${esc(fmt(d,true))}</h3>${scheduler()?`<button class="btn ghost" data-new-day="${d}">+ Richiesta</button>`:''}</div>${onDay(d).map(chip).join('')||'<p class="muted small">Nessun incarico in questa giornata.</p>'}</section>`).join('')}</section><div class="section-row"><h3>Da gestire</h3><button class="btn ghost" data-view="requests">Tutti gli incarichi →</button></div><div class="cards">${state.requests.filter(r=>['pending','counterproposed','incomplete'].includes(r.status)).slice(0,3).map(card).join('')||empty('Tutto aggiornato','Qui troverai le richieste e i lavori che richiedono attenzione.')}</div>`;
}
function installersHtml(){return `<div class="section-row" style="margin-top:0"><p class="muted small">Anagrafiche e accessi dei posatori esterni.</p>${scheduler()?'<button class="btn primary" data-add-installer>+ Nuovo posatore</button>':''}</div><div class="cards">${state.installers.filter(i=>!i.deleted_at).map(i=>`<article class="request-card"><div class="card-top"><span class="avatar">${esc(i.full_name.slice(0,2).toUpperCase())}</span><span class="tag ${i.active?'account-active':'rejected'}">${i.deletion_started_at?'Eliminazione da completare':i.active?'Attivo':'Disattivato'}</span></div><h3>${esc(i.full_name)}</h3><p>${esc(i.company)}<br>${esc(i.email)}<br>${esc(i.phone)}</p><p>${esc(i.notes)}</p>${scheduler()?`<div class="actions">${!i.deletion_started_at?`<button class="btn ghost" data-edit-installer="${i.id}">Modifica</button>`:''}<button class="btn danger" data-delete-installer="${i.id}">${i.deletion_started_at?'Completa eliminazione':'Elimina'}</button>${i.active?`<button class="btn primary" data-for-installer="${i.id}">+ Richiesta</button>`:''}</div>`:''}</article>`).join('')||empty('Inserisci il primo posatore','Crea la sua anagrafica e un accesso personale per inviargli gli incarichi.')}</div>`;}
function notificationsHtml(){return `<div class="section-row" style="margin-top:0"><p class="muted small">Le comunicazioni relative alle pose esterne.</p><button class="btn ghost" data-read-all>Segna tutte come lette</button></div><div class="panel">${state.notifications.map(n=>`<article class="notification${n.read_at?'':' unread'}"><span class="dot ${n.read_at?'':'confirmed'}"></span><div><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p><time>${esc(new Date(n.created_at).toLocaleString('it-IT',{timeZone:'Europe/Rome'}))}</time></div><button class="btn ghost" data-notification="${n.id}">Apri ↗</button></article>`).join('')||empty('Nessuna notifica','Qui compariranno le risposte e gli aggiornamenti degli incarichi.')}</div>`;}
function accountHtml(){return `<section class="panel panel-pad account-panel"><h2>Il tuo account</h2><div class="detail-grid"><div><span>Nome</span><strong>${esc(state.profile.full_name)}</strong></div><div><span>Email di accesso</span><strong>${esc(state.user.email)}</strong></div></div><h3>Password</h3><p class="muted small">Puoi sostituire la password provvisoria con una personale.</p><button type="button" class="btn primary" data-change-password>Cambia password</button></section>`;}
async function changePassword(values){
 const current=String(values.current_password||''),password=String(values.new_password||''),confirm=String(values.confirm_password||'');
 if(!state.user?.id||!state.user.email)throw Error('Accedi di nuovo per cambiare la password.');
 if(!current)throw Error('Inserisci la password attuale.');
 if(password.length<12||password.length>72)throw Error('La nuova password deve contenere da 12 a 72 caratteri.');
 if(password!==confirm)throw Error('Le due nuove password non coincidono.');
 if(password===current)throw Error('Scegli una password diversa da quella attuale.');
 const id=state.user.id;
 // A fresh sign-in verifies the current password and satisfies recent-login requirements.
 const verified=await sb.auth.signInWithPassword({email:state.user.email,password:current});
 if(verified.error){const code=verified.error.code;if(code==='invalid_credentials')throw Error('La password attuale non è corretta.');if(code==='over_request_rate_limit'||verified.error.status===429)throw Error('Troppi tentativi. Attendi qualche minuto e riprova.');throw Error('Non è stato possibile verificare la password attuale. Riprova.');}
 if(verified.data?.user?.id!==id||state.user?.id!==id)throw Error('L’account è cambiato. Ricarica la pagina prima di riprovare.');
 const result=await sb.auth.updateUser({password,current_password:current});
 if(result.error){const code=result.error.code;if(code==='weak_password')throw Error('Scegli una password più sicura, con maiuscole, minuscole, numeri e simboli.');if(code==='same_password')throw Error('Scegli una password diversa da quella attuale.');if(code==='over_request_rate_limit'||result.error.status===429)throw Error('Troppi tentativi. Attendi qualche minuto e riprova.');throw Error('Cambio password non completato. Riprova; se il problema continua, contatta l’ufficio.');}
 if(result.data?.user)state.user=result.data.user;
}
function passwordForm(){
 if(!state.user)return;state.selected=null;
 showModal('Cambia password',`<form id="passwordForm"><div class="password-fields"><label>Email di accesso<input type="email" name="email" autocomplete="username" readonly value="${esc(state.user.email)}"></label><label>Password attuale<input type="password" name="current_password" autocomplete="current-password" required data-password></label><label>Nuova password<input type="password" name="new_password" autocomplete="new-password" minlength="12" maxlength="72" required aria-describedby="passwordHint" data-password></label><p id="passwordHint" class="hint">Scegli da 12 a 72 caratteri. Non condividere la tua password personale.</p><label>Conferma nuova password<input type="password" name="confirm_password" autocomplete="new-password" minlength="12" maxlength="72" required data-password></label><label class="check"><input type="checkbox" data-password-visibility>Mostra password</label></div><p class="error" role="alert" data-form-error></p><div class="form-actions"><button type="button" class="btn ghost" data-close>Annulla</button><button type="submit" class="btn primary">Salva nuova password</button></div></form>`);
 $('passwordForm').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;form.querySelector('[data-form-error]').textContent='';safe(async()=>{await changePassword(dataOf(form));form.reset();closeModal();$('modalBody').replaceChildren();toast('Password aggiornata. Dal prossimo accesso usa la nuova password.');},e.submitter);};
}
function render(){
 if(!state.profile)return;
 $('pageTitle').textContent=({calendar:'Calendario',requests:'Incarichi',installers:'Posatori esterni',notifications:'Notifiche',account:'Account'})[state.view];
 document.querySelectorAll('#nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
 $('content').innerHTML=state.view==='calendar'?calendar():state.view==='requests'?`${stats()}${filterHtml()}<div class="cards">${filtered().map(card).join('')||empty('Nessun incarico','Le richieste che inserirai saranno visibili qui e nel calendario.')}</div>`:state.view==='installers'?installersHtml():state.view==='account'?accountHtml():notificationsHtml();
 const input=$('search');if(input)input.oninput=()=>{state.search=input.value;const pos=input.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos);};
 if($('installerFilter'))$('installerFilter').onchange=e=>{state.filter=e.target.value;render();};if($('statusFilter'))$('statusFilter').onchange=e=>{state.status=e.target.value;render();};
}
function dateFields(ds){const first=ds[0]||today(),last=ds.at(-1)||first;return `<div class="grid2"><label>Dal<input name="range_start" type="date" value="${first}" required data-date-range></label><label>Al<input name="range_end" type="date" value="${last}" required data-date-range></label></div><p class="hint">Seleziona le giornate effettive. Puoi escludere, per esempio, sabato e domenica.</p><div data-date-choices class="date-choices">${range(first,last).map(d=>`<label class="check"><input type="checkbox" name="work_dates" value="${d}"${ds.includes(d)?' checked':''}>${esc(date(d).toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'short'}))}</label>`).join('')}</div>`;}
function readDates(form){if(!form.elements.range_start.value||form.elements.range_start.value>form.elements.range_end.value)throw Error('Controlla le date di inizio e fine.');const ds=new FormData(form).getAll('work_dates').sort();if(!ds.length)throw Error('Seleziona almeno una giornata.');if(ds.some(d=>d<form.elements.range_start.value||d>form.elements.range_end.value))throw Error('Aggiorna le giornate selezionate.');return ds;}
function newRequest(r=null,forInstaller=''){
 if(!scheduler())return;state.selected=null;
 if(!state.installers.some(i=>i.active)){toast('Inserisci prima un posatore esterno.');installerForm();return;}
 const val=k=>esc(r?.[k]||''),ds=r?.work_dates||[state.cursor];
 showModal(r?'Modifica richiesta':'Nuova richiesta di posa',`<form id="requestForm" data-id="${r?.id||''}" data-version="${r?.version||''}"><div class="grid2"><label class="span2">Posatore *<select name="installer_id" required>${state.installers.filter(i=>i.active).map(i=>`<option value="${i.id}"${(r?.installer_id||forInstaller)===i.id?' selected':''}>${esc(i.full_name)}${i.company?` · ${esc(i.company)}`:''}</option>`).join('')}</select></label><label>Riferimento ordine<input name="reference" value="${val('reference')}"></label><label>Cliente / riferimento lavoro<input name="client_name" value="${val('client_name')}"></label><label class="span2">Indirizzo *<input name="address" value="${val('address')}" required placeholder="Via, numero, città, CAP e provincia"></label><label>Piano *<input name="floor" value="${val('floor')}" required placeholder="Es. terra, 1°, 2°…"></label><label>Prezzo (€) *<input name="price" type="number" step="0.01" min="0" required value="${r?.price??''}"></label><label class="span2">Cosa devono fare *<textarea name="description" required rows="4">${val('description')}</textarea></label><label>Ora inizio *<input name="start_time" type="time" value="${r?.start_time?.slice(0,5)||'08:00'}" required></label><label>Ora fine *<input name="end_time" type="time" value="${r?.end_time?.slice(0,5)||'17:00'}" required></label><div class="span2"><h3>Quando</h3>${dateFields(ds)}</div><label class="span2">Altre condizioni<textarea name="conditions" rows="2">${val('conditions')}</textarea></label><div class="notice span2">È compresa la pulizia del cantiere.</div><label class="span2">Allega PDF (anche più di uno)<input name="pdfs" type="file" accept="application/pdf,.pdf" multiple><span class="hint">Massimo 20 MB per file.</span></label></div><p class="error" data-form-error></p><div class="form-actions"><button type="button" class="btn ghost" data-close>Annulla</button><button type="submit" class="btn primary">${r?'Salva e notifica':'Invia richiesta'}</button></div></form>`);
 $('requestForm').onsubmit=e=>{e.preventDefault();safe(async()=>{const form=e.currentTarget,payload=dataOf(form);payload.work_dates=readDates(form);if(payload.end_time<=payload.start_time)throw Error('L’ora di fine deve essere successiva a quella di inizio.');const files=[...form.elements.pdfs.files];validateFiles(files,'pdf');const row=await call('pw_external_save_request',{p_data:payload,p_id:r?.id||null,p_version:r?.version||null});let failed=[];for(const file of files){try{await upload(file,row.id,'pdf');}catch(error){failed.push(`${file.name}: ${error.message}`);}}await refresh();changed();await openRequest(row.id);toast(failed.length?`Richiesta salvata. Alcuni PDF non sono stati caricati: ${failed.join('; ')}. Puoi aggiungerli dal riepilogo.`:'Richiesta inviata al posatore.');},e.submitter);};
}
function installerForm(i=null){if(!scheduler())return;if(i?.deleted_at){toast('Account già eliminato.');return;}if(i?.deletion_started_at){deleteInstallerForm(i.id);return;}state.selected=null;const val=k=>esc(i?.[k]||'');showModal(i?'Modifica posatore':'Nuovo posatore esterno',`<form id="installerForm"><div class="grid2"><label>Nome e cognome *<input name="full_name" required value="${val('full_name')}"></label><label>Azienda<input name="company" value="${val('company')}"></label><label>Email per accedere *<input name="email" type="email" required value="${val('email')}"${i?' readonly':''}></label><label>Telefono<input name="phone" type="tel" value="${val('phone')}"></label><label class="span2">Note anagrafica (condivise con il posatore)<textarea name="notes">${val('notes')}</textarea></label>${i?`<label class="check span2"><input name="active" type="checkbox"${i.active?' checked':''}>Accesso attivo</label>`:'<p class="hint span2">Verrà creato un accesso personale. La password provvisoria comparirà dopo il salvataggio, da comunicare al posatore.</p>'}</div><p class="error" data-form-error></p><div class="form-actions">${i?`<button type="button" class="btn danger installer-delete" data-delete-installer="${i.id}">Elimina posatore</button>`:''}<button class="btn primary" type="submit">${i?'Salva modifiche':'Crea posatore e accesso'}</button></div></form>`);$('installerForm').onsubmit=e=>{e.preventDefault();safe(async()=>{const payload=dataOf(e.currentTarget);payload.active=e.currentTarget.elements.active?.checked??true;if(i){await call('pw_external_save_installer',{p_id:i.id,p_data:payload});await refresh();closeModal();toast('Anagrafica aggiornata.');}else{const bytes=new Uint8Array(18);crypto.getRandomValues(bytes);const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';const password=[...bytes].map(n=>alphabet[n%alphabet.length]).join('')+'!7';await adminAction({action:'create_installer',...payload,password});await refresh();showModal('Accesso creato',`<div class="notice green">Il posatore è pronto a ricevere gli incarichi.</div><p class="hint">Comunica al posatore questi dati. La password non viene mostrata nuovamente.</p><label>Email<div class="credential">${esc(payload.email)}</div></label><br><label>Password provvisoria<div class="credential">${esc(password)}</div></label><p class="hint">Link di accesso: <a href="${esc(location.origin+location.pathname)}">${esc(location.origin+location.pathname)}</a></p><div class="form-actions"><button class="btn primary" data-close>Ho conservato le credenziali</button></div>`);}},e.submitter);};}
async function details(id){const result=await Promise.all([sb.from('external_requests').select('*').eq('id',id).single(),sb.from('external_files').select('*').eq('request_id',id).order('created_at'),sb.from('external_reports').select('*').eq('request_id',id).order('report_date'),sb.from('external_tests').select('*').eq('request_id',id).maybeSingle(),sb.from('external_events').select('*').eq('request_id',id).order('created_at',{ascending:false})]);for(const r of result)if(r.error)throw Error(r.error.message);return {request:result[0].data,files:result[1].data||[],reports:result[2].data||[],test:result[3].data,events:result[4].data||[]};}
function filesHtml(files,kind){const rows=files.filter(f=>f.kind===kind);return kind==='pdf'?`<div class="files">${rows.map(f=>`<div class="file-row"><span>▤ ${esc(f.file_name)}</span><button data-file="${f.id}">Apri PDF ↗</button></div>`).join('')||'<p class="hint">Nessun PDF allegato.</p>'}</div>`:`<div class="photo-grid">${rows.map(f=>`<button class="photo" data-file="${f.id}"><img data-photo="${f.id}" alt="${esc(f.file_name)}" loading="lazy"><span>${esc(f.file_name)}</span></button>`).join('')}</div>${!rows.length?'<p class="hint">Nessuna foto caricata.</p>':''}`;}
function uploadHtml(id,kind){return `<label class="upload">${kind==='pdf'?'Aggiungi PDF':`Aggiungi foto ${kind==='before'?'prima dei':'dopo i'} lavori`}<input type="file" data-upload="${kind}" data-request="${id}" accept="${kind==='pdf'?'application/pdf,.pdf':'image/jpeg,image/png,image/webp,image/heic,image/heif,.heic,.heif'}" multiple><span class="hint">Puoi selezionare più file. Massimo 20 MB ciascuno.</span></label>`;}
async function openRequest(id){
 const detail=await details(id);state.selected=detail;const {request:r,files,reports,test,events}=detail,i=installer(r.installer_id),work=locked(r),write=scheduler()||myRequest(r);
 showModal(r.client_name||r.address,`${tag(r)}<div class="detail-grid">${[['Posatore',`${i?.full_name||''}${i?.company?` · ${i.company}`:''}`],['Riferimento',r.reference||'—'],['Prezzo',money(r.price)],['Indirizzo',r.address],['Piano',r.floor],['Giornate',datesLabel(r.work_dates)],['Orario',`${r.start_time.slice(0,5)}–${r.end_time.slice(0,5)}`]].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><p class="detail-description">${esc(r.description)}</p><div class="notice">${esc(r.conditions)}${r.conditions?'\n\n':''}È compresa la pulizia del cantiere.</div><p class="hint">Per maggiori informazioni o chiarimenti contattare il numero <a href="tel:+393669750942">366 975 0942</a>.</p>${r.status==='counterproposed'?`<div class="notice"><strong>Controproposta del posatore</strong><br>${esc(datesLabel(r.proposed_dates))}<br>${esc(r.response_note)}${scheduler()?`<div class="actions" style="margin-top:14px"><button class="btn primary" data-response="approve_dates">Accetta queste date</button><button class="btn ghost" data-response="reject_dates">Non accettare le date</button></div>`:'<p class="hint">In attesa della risposta dell’ufficio. Le nuove date non sono ancora impegnate.</p>'}</div>`:''}${r.status==='rejected'?`<div class="notice">Incarico rifiutato.${r.response_note?`<br>${esc(r.response_note)}`:''}</div>`:''}${myRequest(r)&&r.status==='pending'?`<form id="responseForm" class="inline-form"><label class="check"><input type="checkbox" name="accept_conditions">Ho letto le condizioni e confermo la pulizia del cantiere.</label><div class="actions" style="margin-top:17px"><button class="btn primary" type="submit">Accetta incarico</button><button class="btn ghost" type="button" data-counter>Proponi altre date</button><button class="btn danger" type="button" data-decline>Rifiuta incarico</button></div></form>`:''}${scheduler()&&['pending','counterproposed'].includes(r.status)?'<div class="actions"><button class="btn ghost" data-edit-request>Modifica richiesta</button></div>':''}<section class="detail-section"><h3>Documenti allegati</h3>${filesHtml(files,'pdf')}${scheduler()?uploadHtml(r.id,'pdf'):''}</section>${work?`<section class="detail-section"><h3>Foto prima dei lavori</h3>${filesHtml(files,'before')}${write?uploadHtml(r.id,'before'):''}</section><section class="detail-section"><h3>Foto dopo i lavori</h3>${filesHtml(files,'after')}${write?uploadHtml(r.id,'after'):''}</section><section class="detail-section"><div class="section-row" style="margin-top:0"><h3>Rapportini giornalieri</h3>${write&&r.status!=='completed'?'<button class="btn primary" data-report>+ Compila rapportino</button>':''}</div>${reports.map(a=>`<div class="notice${a.incomplete?'':' green'}"><strong>${esc(fmt(a.report_date))}${a.incomplete?' · Lavoro incompleto':''}</strong><br>${esc(a.description)}${a.operators?`<br>Posatori: ${esc(a.operators)}`:''}${a.hours!=null?` · ${a.hours} ore`:''}${a.incomplete?`<br><strong>Motivo:</strong> ${esc(a.reason)}`:''}${write&&r.status!=='completed'?`<br><button class="btn ghost" data-report="${a.report_date}">Aggiorna rapportino</button>`:''}</div>`).join('')||'<p class="hint">Il rapportino si compila nelle giornate della posa, fino alla data di oggi.</p>'}</section><section class="detail-section"><div class="section-row" style="margin-top:0"><h3>Collaudo di fine lavori</h3>${write&&r.status!=='completed'?'<button class="btn primary" data-test>Compila collaudo</button>':''}</div>${test?`<div class="notice${test.outcome==='conforme'?' green':''}"><strong>${test.outcome==='conforme'?'Conforme · lavori completati':'Lavoro da completare'}</strong><br>${esc(fmt(test.test_date))} · ${esc(test.operator_name)}<br>${esc(test.checks)}<br>Pulizia: ${test.cleaned?'eseguita':'da eseguire'}${test.notes?`<br>${esc(test.notes)}`:''}</div>`:'<p class="hint">Da compilare alla conclusione dei lavori.</p>'}</section>`:''}${office()?'<section class="detail-section"><h3>Fascicolo dell’incarico</h3><p class="hint">Riepilogo, PDF, rapportini, foto prima e dopo e collaudo, raccolti in un unico file ZIP.</p><button class="btn primary" data-export>Esporta fascicolo ↓</button></section>':''}<section class="detail-section"><h3>Storico aggiornamenti</h3><div class="timeline">${events.slice(0,30).map(e=>`<p><strong>${esc(e.message)}</strong>${esc(new Date(e.created_at).toLocaleString('it-IT',{timeZone:'Europe/Rome'}))}</p>`).join('')}</div></section><p class="error" data-form-error></p>`);
 const response=$('responseForm');if(response)response.onsubmit=e=>{e.preventDefault();safe(()=>respond('accept',{accept_conditions:response.elements.accept_conditions.checked}),e.submitter);};
 for(const img of $('modalBody').querySelectorAll('[data-photo]')){const f=files.find(x=>x.id===img.dataset.photo);sb.storage.from('pw-external-private').createSignedUrl(f.storage_path,600).then(({data,error})=>{if(data?.signedUrl&&img.isConnected)img.src=data.signedUrl;else if(error)img.alt='Anteprima non disponibile · '+f.file_name;});img.onerror=()=>{img.alt=f.file_name;img.style.height='45px';};}
}
async function respond(action,payload={}){const r=state.selected.request;await call('pw_external_respond',{p_id:r.id,p_action:action,p_version:r.version,p_data:payload});await refresh();changed();await openRequest(r.id);toast(action==='propose'?'Controproposta inviata all’ufficio.':'Risposta registrata.');}
function counterForm(){const r=state.selected.request,accepted=$('responseForm')?.elements.accept_conditions.checked;if(!accepted){toast('Conferma di aver letto le condizioni e la pulizia del cantiere.');return;}const suggested=r.work_dates.map(d=>shift(d,1));$('modalBody').innerHTML=`<form id="counterForm"><h3>Proponi altre date</h3><p class="hint">L’ufficio riceverà la controproposta. Le date saranno confermate dopo la sua accettazione.</p>${dateFields(suggested)}<label style="margin-top:20px">Messaggio per l’ufficio<textarea name="note"></textarea></label><p class="error" data-form-error></p><div class="form-actions"><button class="btn ghost" type="button" data-back>Torna al riepilogo</button><button class="btn primary" type="submit">Invia controproposta</button></div></form>`;$('counterForm').onsubmit=e=>{e.preventDefault();safe(()=>respond('propose',{dates:readDates(e.currentTarget),note:e.currentTarget.elements.note.value,accept_conditions:true}),e.submitter);};}
function declineForm(){const r=state.selected.request;$('modalBody').innerHTML=`<form id="declineForm"><h3>Rifiuta completamente l’incarico</h3><p class="hint">Se vuoi proporre soltanto date diverse, torna al riepilogo e scegli “Proponi altre date”.</p><label>Motivo o messaggio (facoltativo)<textarea name="note"></textarea></label><p class="error" data-form-error></p><div class="form-actions"><button class="btn ghost" type="button" data-back>Torna al riepilogo</button><button class="btn danger" type="submit">Conferma rifiuto</button></div></form>`;$('declineForm').onsubmit=e=>{e.preventDefault();safe(()=>respond('reject',{note:e.currentTarget.elements.note.value}),e.submitter);};}
function reportForm(day=''){
 const {request:r,reports}=state.selected,allowed=r.work_dates.filter(d=>d<=today());if(!allowed.length){toast('Il rapportino sarà disponibile dal primo giorno della posa.');return;}const selected=day||(allowed.includes(today())?today():allowed.at(-1));const old=reports.find(x=>x.report_date===selected),v=k=>esc(old?.[k]??'');
 $('modalBody').innerHTML=`<form id="reportForm"><h3>Rapportino giornaliero</h3><div class="grid2"><label>Giornata *<select name="report_date" id="reportDay">${allowed.map(d=>`<option value="${d}"${d===selected?' selected':''}>${esc(fmt(d))}</option>`).join('')}</select></label><label>Ore lavorate<input name="hours" type="number" min="0" max="24" step="0.25" value="${v('hours')}"></label><label class="span2">Posatori presenti<input name="operators" value="${v('operators')}"></label><label class="span2">Lavori eseguiti *<textarea name="description" required rows="4">${v('description')}</textarea></label><label class="check span2"><input name="incomplete" id="incomplete" type="checkbox"${old?.incomplete?' checked':''}>Lavoro incompleto: non è stato possibile terminare la posa</label><label class="span2" id="reasonWrap"${old?.incomplete?'':' hidden'}>Perché non è stato possibile finire e cosa resta da fare *<textarea name="reason"${old?.incomplete?' required':''}>${v('reason')}</textarea></label></div><p class="error" data-form-error></p><div class="form-actions"><button class="btn ghost" type="button" data-back>Annulla</button><button class="btn primary" type="submit">Salva e avvisa l’ufficio</button></div></form>`;
 $('reportDay').onchange=e=>reportForm(e.target.value);$('incomplete').onchange=e=>{const label=$('reasonWrap');label.hidden=!e.target.checked;label.querySelector('textarea').required=e.target.checked;};
 $('reportForm').onsubmit=e=>{e.preventDefault();safe(async()=>{const form=e.currentTarget,payload=dataOf(form);payload.incomplete=form.elements.incomplete.checked;if(!payload.incomplete)payload.reason='';await call('pw_external_save_report',{p_id:r.id,p_version:r.version,p_data:payload});await refresh();changed();await openRequest(r.id);toast('Rapportino salvato.');},e.submitter);};
}
function testForm(){const {request:r,test:t}=state.selected;if(r.work_dates[0]>today()){toast('Il collaudo si compila dopo l’inizio dei lavori.');return;}$('modalBody').innerHTML=`<form id="testForm"><h3>Collaudo di fine lavori</h3><div class="grid2"><label>Data *<input name="test_date" type="date" value="${t?.test_date||today()}" min="${r.work_dates[0]}" max="${today()}" required></label><label>Esito *<select name="outcome" id="testOutcome"><option value="conforme">Conforme · lavori completati</option><option value="da_completare"${t?.outcome==='da_completare'?' selected':''}>Da completare</option></select></label><label class="span2">Verifiche eseguite *<textarea name="checks" required rows="4" placeholder="Funzionamento dei serramenti, posa, finiture e verifiche finali…">${esc(t?.checks||'')}</textarea></label><label class="span2">Nome e cognome del posatore che esegue il collaudo *<input name="operator_name" required value="${esc(t?.operator_name||state.profile.full_name)}"></label><label class="check span2"><input name="cleaned" id="testCleaned" type="checkbox"${t?.cleaned?' checked':''}>Confermo la pulizia del cantiere</label><label class="span2">Note / lavori da completare<textarea name="notes" id="testNotes">${esc(t?.notes||'')}</textarea></label></div><p class="hint">Con esito conforme, il collaudo conclude l’incarico. Se restano problemi, indica cosa manca.</p><p class="error" data-form-error></p><div class="form-actions"><button class="btn ghost" type="button" data-back>Annulla</button><button class="btn primary" type="submit">Salva collaudo</button></div></form>`;
 const constraints=()=>{$('testCleaned').required=$('testOutcome').value==='conforme';$('testNotes').required=$('testOutcome').value==='da_completare';};$('testOutcome').onchange=constraints;constraints();$('testForm').onsubmit=e=>{e.preventDefault();safe(async()=>{const form=e.currentTarget,payload=dataOf(form);payload.cleaned=form.elements.cleaned.checked;await call('pw_external_save_test',{p_id:r.id,p_version:r.version,p_data:payload});await refresh();changed();await openRequest(r.id);toast('Collaudo salvato.');},e.submitter);};}
function validateFiles(files,kind){for(const f of files){if(f.size>20*1024*1024)throw Error(`${f.name}: il file supera 20 MB.`);if(kind==='pdf'&&!/\.pdf$/i.test(f.name))throw Error('Puoi allegare solo file PDF.');if(kind!=='pdf'&&!/\.(jpe?g|png|webp|heic|heif)$/i.test(f.name))throw Error('Sono accettate foto JPG, PNG, WebP, HEIC e HEIF.');}}
async function upload(file,id,kind){validateFiles([file],kind);const mime=kind==='pdf'?'application/pdf':({jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',heic:'image/heic',heif:'image/heif'})[file.name.split('.').at(-1).toLowerCase()];const path=`requests/${id}/${kind}/${state.user.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const result=await sb.storage.from('pw-external-private').upload(path,file,{contentType:mime,upsert:false});if(result.error)throw Error(result.error.message);try{return await call('pw_external_register_file',{p_id:id,p_kind:kind,p_path:path,p_name:file.name});}catch(error){await sb.storage.from('pw-external-private').remove([path]);throw error;}}
async function openFile(id){const file=state.selected.files.find(f=>f.id===id);if(!file)return;const popup=window.open('about:blank','_blank');try{const r=await sb.storage.from('pw-external-private').createSignedUrl(file.storage_path,300);if(r.error)throw Error(r.error.message);if(popup){popup.opener=null;popup.location.href=r.data.signedUrl;}else{const a=document.createElement('a');a.href=r.data.signedUrl;a.target='_blank';a.rel='noopener';a.textContent='Apri allegato';$('modalBody').prepend(a);toast('Usa il collegamento “Apri allegato”.');}}catch(e){popup?.close();throw e;}}
async function openNotification(id){const n=state.notifications.find(x=>x.id===id)||((await sb.from('notifications').select('*').eq('id',id).eq('recipient_id',state.user.id).maybeSingle()).data);if(!n)return;if(!n.read_at){const result=await sb.from('notifications').update({read_at:new Date().toISOString()}).eq('id',n.id).eq('recipient_id',state.user.id);if(result.error)throw Error(result.error.message);}await refresh();if(n.entity_type==='external_pose')await openRequest(n.entity_id);}
const VAPID='BL6oByyaj54jYYOOxsXtLOI0zVOCuTVWWTwSx4NUj15s15P-2_98iLRekpnFDL9hdtRhpopcHgDQYWOllxfvXuQ';
async function enablePush(){if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('Su iPhone, aggiungi prima l’app alla schermata Home da Safari e riaprila dall’icona.');if(await Notification.requestPermission()!=='granted')throw Error('Consenti le notifiche nelle impostazioni del browser.');const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub){const raw=atob(VAPID.replace(/-/g,'+').replace(/_/g,'/'));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(raw,c=>c.charCodeAt(0))});}const j=sub.toJSON();await call('register_push_subscription',{p_endpoint:j.endpoint,p_p256dh:j.keys.p256dh,p_auth:j.keys.auth,p_user_agent:navigator.userAgent});$('pushButton').textContent='Notifiche attive ✓';toast('Notifiche attivate su questo dispositivo.');}
async function bindExistingPush(){try{if(!('serviceWorker'in navigator))return;const reg=await navigator.serviceWorker.getRegistration('./'),sub=await reg?.pushManager?.getSubscription();if(sub){const j=sub.toJSON();await call('register_push_subscription',{p_endpoint:j.endpoint,p_p256dh:j.keys.p256dh,p_auth:j.keys.auth,p_user_agent:navigator.userAgent});$('pushButton').textContent='Notifiche attive ✓';}}catch(error){console.warn('Associazione notifiche',error);}}
async function logout(){await safe(async()=>{if('serviceWorker'in navigator){const scopes=[new URL('./',document.baseURI).href,new URL('../',document.baseURI).href];for(const reg of await navigator.serviceWorker.getRegistrations()){if(!scopes.includes(reg.scope))continue;const sub=await reg.pushManager?.getSubscription();if(sub){const r=await sb.from('push_subscriptions').delete().eq('user_id',state.user.id).eq('endpoint',sub.endpoint);if(r.error&&!await sub.unsubscribe())throw Error('Impossibile scollegare le notifiche. Riprova.');}}}if(state.channel)await sb.removeChannel(state.channel);await sb.auth.signOut({scope:'local'});location.reload();});}
async function boot(session){state.user=session.user;const p=await sb.from('profiles').select('*').eq('id',state.user.id).single();if(p.error||!p.data?.active)throw Error('Account non abilitato. Contatta l’ufficio.');state.profile=p.data;await load();if(!office()&&!state.installers.some(i=>i.profile_id===state.user.id&&i.active))throw Error('Questo account non è abilitato a PW Posa Esterni.');$('login').hidden=true;$('shell').hidden=false;$('accountName').textContent=state.profile.full_name;$('accountRole').textContent=scheduler()?'Ufficio':office()?'Ufficio · lettura':'Posatore esterno';$('accountInitial').textContent=state.profile.full_name.slice(0,2).toUpperCase();document.querySelectorAll('.office-only').forEach(e=>e.hidden=!office());document.querySelectorAll('.scheduler-only').forEach(e=>e.hidden=!scheduler());render();bindExistingPush();
 if(state.channel)await sb.removeChannel(state.channel);let timer;const updated=()=>{clearTimeout(timer);timer=setTimeout(()=>safe(refresh),500);};state.channel=sb.channel(`pw-external-${state.user.id}`).on('postgres_changes',{event:'*',schema:'public',table:'external_requests'},updated).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:`recipient_id=eq.${state.user.id}`},updated).subscribe();
 const params=new URLSearchParams(location.search);if(params.get('request'))await openRequest(params.get('request'));else if(params.get('notification'))await openNotification(params.get('notification'));
}
$('loginForm').onsubmit=e=>{e.preventDefault();const b=e.submitter;b.disabled=true;$('loginError').textContent='';(async()=>{try{const values=dataOf(e.currentTarget),r=await sb.auth.signInWithPassword({email:values.email,password:values.password});if(r.error)throw Error('Email o password non corrette.');await boot(r.data.session);}catch(error){$('loginError').textContent=error.message;state.profile=null;}finally{b.disabled=false;}})();};
$('togglePassword').onclick=()=>{const p=$('loginPassword'),show=p.type==='password';p.type=show?'text':'password';$('togglePassword').textContent=show?'Nascondi':'Mostra';};
$('closeModal').onclick=closeModal;$('modal').addEventListener('cancel',()=>{$('passwordForm')?.reset();state.selected=null;if(document.body.classList.contains('embedded'))window.parent.postMessage({type:'pw-external-close'},location.origin);});$('newRequest').onclick=()=>newRequest();$('refresh').onclick=e=>safe(refresh,e.currentTarget);$('pushButton').onclick=e=>safe(enablePush,e.currentTarget);$('logout').onclick=logout;$('mobileLogout').onclick=logout;
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-toggle-filters')){state.filterOpen=!state.filterOpen;render();}else if(b.dataset.view){state.view=b.dataset.view;render();}else if(b.dataset.open)safe(()=>openRequest(b.dataset.open),b);else if(b.hasAttribute('data-close'))closeModal();else if(b.dataset.day){state.cursor=b.dataset.day;state.mode='day';render();}else if(b.dataset.newDay){state.cursor=b.dataset.newDay;newRequest();}else if(b.dataset.mode){state.mode=b.dataset.mode;render();}else if(b.dataset.step){const step=Number(b.dataset.step);if(state.mode==='month'){const d=date(state.cursor);d.setDate(1);d.setMonth(d.getMonth()+step);state.cursor=iso(d);}else state.cursor=shift(state.cursor,step*(state.mode==='week'?7:1));render();}else if(b.hasAttribute('data-today')){state.cursor=today();render();}else if(b.hasAttribute('data-change-password'))passwordForm();else if(b.hasAttribute('data-add-installer'))installerForm();else if(b.dataset.deleteInstaller)deleteInstallerForm(b.dataset.deleteInstaller);else if(b.dataset.editInstaller)installerForm(installer(b.dataset.editInstaller));else if(b.dataset.forInstaller)newRequest(null,b.dataset.forInstaller);else if(b.hasAttribute('data-edit-request'))newRequest(state.selected.request);else if(b.dataset.response)safe(()=>respond(b.dataset.response),b);else if(b.hasAttribute('data-counter'))counterForm();else if(b.hasAttribute('data-decline'))declineForm();else if(b.hasAttribute('data-back'))safe(()=>openRequest(state.selected.request.id),b);else if(b.hasAttribute('data-report'))reportForm(b.dataset.report);else if(b.hasAttribute('data-test'))testForm();else if(b.dataset.file)safe(()=>openFile(b.dataset.file),b);else if(b.dataset.notification)safe(()=>openNotification(b.dataset.notification),b);else if(b.hasAttribute('data-read-all'))safe(async()=>{const r=await sb.from('notifications').update({read_at:new Date().toISOString()}).eq('recipient_id',state.user.id).like('notification_type','external_%').is('read_at',null);if(r.error)throw Error(r.error.message);await refresh();},b);else if(b.hasAttribute('data-export'))safe(()=>window.PWExternalExport(state.selected),b);});
document.addEventListener('change',e=>{const input=e.target;if(input.hasAttribute('data-password-visibility')){input.closest('form').querySelectorAll('[data-password]').forEach(field=>{field.type=input.checked?'text':'password';});}else if(input.hasAttribute('data-date-range')){const form=input.closest('form'),a=form.elements.range_start.value,b=form.elements.range_end.value;if(a&&b&&a<=b)safe(async()=>{form.querySelector('[data-date-choices]').innerHTML=range(a,b).map(d=>`<label class="check"><input type="checkbox" name="work_dates" value="${d}" checked>${esc(date(d).toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'short'}))}</label>`).join('');});}else if(input.dataset.upload){const files=[...input.files];safe(async()=>{validateFiles(files,input.dataset.upload);input.disabled=true;let failures=[];for(const f of files){try{await upload(f,input.dataset.request,input.dataset.upload);}catch(error){failures.push(`${f.name}: ${error.message}`);}}await refresh();changed();await openRequest(input.dataset.request);toast(failures.length?`Alcuni file non sono stati caricati: ${failures.join('; ')}`:`${files.length} file caricati.`);}).finally(()=>{input.disabled=false;});}});
if(new URLSearchParams(location.search).get('embed')==='1')document.body.classList.add('embedded');
if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js',{scope:'./'}).catch(()=>toast('Installazione app non disponibile. Puoi continuare dal browser.'));
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.user)safe(refresh);});setInterval(()=>{if(document.visibilityState==='visible'&&state.user)safe(refresh);},30000);
sb.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_IN'&&state.user&&session?.user.id!==state.user.id){location.reload();return;}if(event==='SIGNED_OUT'&&state.user){if('serviceWorker'in navigator)navigator.serviceWorker.getRegistration('./').then(async r=>{const sub=await r?.pushManager?.getSubscription();if(sub)await sub.unsubscribe();}).catch(()=>{});state.user=null;state.profile=null;state.requests=[];state.installers=[];if(state.channel)sb.removeChannel(state.channel);$('shell').hidden=true;$('login').hidden=false;closeModal();}});
window.PWExternalApp={sb,state,office,scheduler,installer,fmt,money,datesLabel,toast,esc,details,openRequest,refresh};
(async()=>{try{const r=await sb.auth.getSession();if(r.error)throw r.error;if(r.data.session)await boot(r.data.session);}catch(error){$('loginError').textContent=error.message||'Accesso non disponibile.';}})();
})();
